mapper.select:
    SELECT sla_clock_id, ticket_id, status, clock_type, deadline_at,
       reminder_due_at, updated_at
FROM sla_clock
WHERE tenant_id=#{tenantId} AND updated_at >= #{updatedAt}
ORDER BY updated_at, sla_clock_id  LIMIT #{limit}

mapper.update:
    UPDATE sla_clock
SET status = 'SATISFIED_ON_TIME',
    milestone_at = #{now},
    satisfied_at = #{now2},
    lock_version = lock_version + 1,
    updated_at = CASE WHEN updated_at >= #{now3}
        THEN TIMESTAMPADD(MICROSECOND, 1, updated_at) ELSE #{now4} END,
    updated_by_type = #{actorType},
    updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND sla_clock_id = #{slaClockId}
  AND status = 'RUNNING' AND lock_version = #{expectedLockVersion}

    UPDATE sla_clock
SET status = 'BREACHED',
    breached_at = #{now},
    lock_version = lock_version + 1,
    updated_at = CASE WHEN updated_at >= #{now2}
        THEN TIMESTAMPADD(MICROSECOND, 1, updated_at) ELSE #{now3} END,
    updated_by_type = #{actorType},
    updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND sla_clock_id = #{slaClockId}
  AND status = 'RUNNING' AND lock_version = #{expectedLockVersion}

    UPDATE sla_clock
SET status = 'SATISFIED_LATE',
    milestone_at = #{now},
    satisfied_at = #{now2},
    lock_version = lock_version + 1,
    updated_at = CASE WHEN updated_at >= #{now3}
        THEN TIMESTAMPADD(MICROSECOND, 1, updated_at) ELSE #{now4} END,
    updated_by_type = #{actorType},
    updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND sla_clock_id = #{slaClockId}
  AND status = 'BREACHED' AND lock_version = #{expectedLockVersion}

    UPDATE sla_clock
SET updated_at = CASE WHEN updated_at >= #{now}
    THEN TIMESTAMPADD(MICROSECOND, 1, updated_at) ELSE #{now2} END,
    updated_by_type='SCHEDULER',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND sla_clock_id=#{slaClockId}
